from donations import load_donations, ROWS
from summary import DonationSummary

MEAN = sum(v for _, v in ROWS) / len(ROWS)


def test_mean_of_stored():
    assert abs(DonationSummary(load_donations()).mean_pounds() - MEAN) < 1e-9


def test_count_then_mean():
    s = DonationSummary(load_donations())
    assert s.count() == len(ROWS) and abs(s.mean_pounds() - MEAN) < 1e-9


def test_mean_twice():
    s = DonationSummary(load_donations())
    s.mean_pounds()
    assert abs(s.mean_pounds() - MEAN) < 1e-9


def test_list_input():
    assert abs(DonationSummary(list(load_donations())).mean_pounds() - MEAN) < 1e-9


def test_empty():
    assert DonationSummary(iter([])).mean_pounds() == 0.0
